package vn.svframe.svframelib.skill.parameter.value;import net.minecraft.server.network.ServerPlayerEntity;import vn.svframe.mythiclibfabric.runtime.script.ExpressionRuntime;import java.util.Map;public class CustomScalingFormula implements ScalingFormula{private final String expression;private final ExpressionRuntime runtime=new ExpressionRuntime();public CustomScalingFormula(String expression){this.expression=expression;}public double evaluate(int level,ServerPlayerEntity player){return runtime.evaluate(expression,Map.of("level",(double)Math.max(1,level)));}public boolean isInteger(){return false;}}